INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-24', 'es', 'LAIKA 64 3.5.2: ya conecta aunque la fecha esté mal', 'Si la fecha de tu Xbox estaba mal (pasa al desconectarla), LAIKA no conectaba: ni en línea, ni portadas, ni texturas. Ya está corregido. Además, una nueva intro con salto al hiperespacio. Actualiza desde LAIKA.'),
 ('2026-11-24', 'en', 'LAIKA 64 3.5.2: connects even with a wrong date', 'If your Xbox date was wrong (it happens when unplugged), LAIKA could not connect: no online, box art or textures. Fixed now. Plus a new intro with a jump to hyperspace. Update from LAIKA.'),
 ('2026-11-24', 'pt', 'LAIKA 64 3.5.2: conecta mesmo com a data errada', 'Se a data do seu Xbox estava errada (acontece ao desligá-lo da tomada), o LAIKA não conectava: nem online, nem capas, nem texturas. Corrigido. E uma nova intro com salto ao hiperespaço. Atualize pelo LAIKA.'),
 ('2026-11-24', 'fr', 'LAIKA 64 3.5.2 : connexion même avec une date fausse', 'Si la date de votre Xbox était fausse (après débranchement), LAIKA ne se connectait pas : ni en ligne, ni jaquettes, ni textures. C''est corrigé. Et une nouvelle intro avec un saut dans l''hyperespace. Mettez à jour depuis LAIKA.'),
 ('2026-11-24', 'it', 'LAIKA 64 3.5.2: si connette anche con la data sbagliata', 'Se la data della tua Xbox era sbagliata (succede staccandola), LAIKA non si connetteva: niente online, copertine o texture. Corretto. In più una nuova intro con salto nell''iperspazio. Aggiorna da LAIKA.'),
 ('2026-11-24', 'de', 'LAIKA 64 3.5.2: verbindet auch mit falschem Datum', 'War das Datum deiner Xbox falsch (passiert nach dem Ausstecken), verband sich LAIKA nicht: kein Online, keine Cover, keine Texturen. Behoben. Dazu ein neues Intro mit Sprung in den Hyperraum. Aktualisiere in LAIKA.'),
 ('2026-11-24', 'ru', 'LAIKA 64 3.5.2: подключение даже при неверной дате', 'Если дата Xbox была неверной (бывает после отключения от сети), LAIKA не подключался: ни онлайн, ни обложки, ни текстуры. Исправлено. А также новое интро с прыжком в гиперпространство. Обновитесь в LAIKA.');
